package com.quickcart.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ApiException.class) ResponseEntity<Map<String,Object>> api(ApiException e){return body(e.status,e.getMessage());} @ExceptionHandler(Exception.class) ResponseEntity<Map<String,Object>> all(Exception e){return body(HttpStatus.INTERNAL_SERVER_ERROR,"Unexpected server error");} private ResponseEntity<Map<String,Object>> body(HttpStatus s,String m){Map<String,Object>x=new LinkedHashMap<>();x.put("timestamp",Instant.now());x.put("status",s.value());x.put("code",s.getReasonPhrase());x.put("message",m);return ResponseEntity.status(s).body(x);} }
